<template><div class="settings"><h2>AI 配置</h2><n-alert type="info">已适配 DeepSeek 官方 API，可保存密钥并测试连接。只需开启一个全局 AI 研判开关：漏洞情报推送成功后异步调用 DeepSeek；相同 CVE 不重复分析。</n-alert><n-card title="AI 自动研判总开关" style="margin-top:16px"><n-space align="center"><n-switch v-model:value="form.enabled"/><strong>{{form.enabled?"已开启":"已关闭"}}</strong><n-button type="primary" :loading="saving" @click="save">保存开关</n-button></n-space><p>仅推送成功的漏洞情报触发 AI；安全文章不触发，相同 CVE 不重复分析。</p></n-card><n-card title="已保存的 AI 配置列表" style="margin-top:16px"><n-alert type="info">目前支持一条 DeepSeek 配置，重复保存会更新这一条，不会新增记录。</n-alert><n-data-table :columns="configColumns" :data="configRows" :row-key="r=>r.id"/><n-button style="margin-top:12px" @click="$router.push('/push-settings')">去推送配置设置 AI 联动</n-button></n-card><n-card title="当前 AI 配置" style="margin-top:16px"><n-descriptions bordered :column="2"><n-descriptions-item label="服务商">DeepSeek</n-descriptions-item><n-descriptions-item label="模型">{{form.model||"deepseek-chat"}}</n-descriptions-item><n-descriptions-item label="密钥状态">{{form.has_api_key?"已配置":"未配置"}}</n-descriptions-item><n-descriptions-item label="启用 Skill">{{options.find(x=>x.value===form.active_skill)?.label||"不使用"}}</n-descriptions-item></n-descriptions></n-card><n-card id="ai-model-settings" title="模型设置" style="margin-top:16px"><n-form-item label="服务商"><n-input value="DeepSeek" disabled/></n-form-item><n-form-item label="模型"><n-select v-model:value="form.model" :options="modelOptions"/></n-form-item><n-form-item label="API 地址"><n-input value="https://api.deepseek.com/chat/completions" disabled/></n-form-item><n-form-item label="DeepSeek API Key（留空保持原密钥）"><n-input v-model:value="form.api_key" type="password" show-password-on="click" placeholder="sk-..."/></n-form-item><n-text depth="3">{{form.has_api_key?'已保存 API Key（不会回显）':'尚未保存 API Key'}}</n-text><n-form-item label="系统提示词"><n-input v-model:value="form.system_prompt" type="textarea" :rows="10"/></n-form-item><n-form-item label="启用 Skill"><n-select v-model:value="form.active_skill" :options="options"/></n-form-item><n-space><n-button type="primary" :loading="saving" @click="save">保存配置</n-button><n-button :loading="testing" @click="test">测试 DeepSeek 连接</n-button><n-button @click="preview">预览最终提示词</n-button></n-space></n-card><n-card title="最近 AI 分析结果" style="margin-top:16px"><n-space style="margin-bottom:12px"><n-button @click="loadResults">刷新结果</n-button><n-text depth="3">推送成功后后台异步研判，失败不影响推送。</n-text></n-space><n-data-table :columns="resultColumns" :data="results" :row-key="r=>r.key"/><n-modal v-model:show="resultVisible" preset="card" title="AI 分析详情" style="width:min(900px,95vw)"><pre style="white-space:pre-wrap">{{selectedResult}}</pre></n-modal></n-card><n-modal v-model:show="visible" preset="card" title="最终提示词" style="width:min(850px,95vw)"><pre style="white-space:pre-wrap">{{prompt}}</pre></n-modal></div></template>
<script setup>
import {ref,computed,onMounted,h} from 'vue'
import axios from 'axios'
import {NAlert,NCard,NFormItem,NInput,NSelect,NButton,NSpace,NModal,NText,NDescriptions,NDescriptionsItem,NDataTable,NSwitch,useMessage} from 'naive-ui'
const msg=useMessage(),saving=ref(false),testing=ref(false)
const modelOptions=[{label:'DeepSeek V3（deepseek-chat）',value:'deepseek-chat'},{label:'DeepSeek R1（deepseek-reasoner）',value:'deepseek-reasoner'}]
const form=ref({provider:'DeepSeek',model:'deepseek-chat',api_url:'https://api.deepseek.com',api_key:'',enabled:false,has_api_key:false,system_prompt:'',active_skill:0})
const configRows=ref([])
const configColumns=[{title:'名称',key:'name'},{title:'模型',key:'model'},{title:'密钥状态',key:'keyStatus'},{title:'Skill',key:'skill'},{title:'操作',key:'actions',render:()=>h(NButton,{size:'small',onClick:()=>document.getElementById('ai-model-settings')?.scrollIntoView({behavior:'smooth'})},()=> '编辑')}]
const skills=ref([]),visible=ref(false),prompt=ref(''),results=ref([]),resultVisible=ref(false),selectedResult=ref('')
const resultColumns=[{title:'CVE',key:'key'},{title:'来源',key:'source'},{title:'状态',key:'status',render:r=>({pending:'待分析',running:'分析中',success:'成功',failed:'失败'}[r.status]||r.status)},{title:'模型',key:'model'},{title:'分析时间',key:'created_at'},{title:'操作',key:'actions',render:r=>h(NButton,{size:'small',onClick:()=>{selectedResult.value=r.result||r.error||'尚无结果';resultVisible.value=true}},()=> '查看分析')}]
async function loadResults(){try{results.value=(await http.get('/results')).data.data}catch(e){msg.error(e.message)}}
const options=computed(()=>[{label:'不使用 Skill',value:0},...skills.value.map(x=>({label:x.name,value:x.id}))])
const http=axios.create({baseURL:'/api/v1/settings/ai'})
http.interceptors.request.use(c=>{c.headers.Authorization='Bearer '+(localStorage.getItem('token')||'');return c})
async function load(){try{const saved=(await http.get('')).data.data;form.value={...form.value,...saved,api_key:'',provider:'DeepSeek',api_url:'https://api.deepseek.com',model:saved.model||'deepseek-chat'};skills.value=(await http.get('/skills')).data.data;configRows.value=[{id:1,name:'DeepSeek 默认配置',model:form.value.model,keyStatus:form.value.has_api_key?'已保存':'未配置',skill:skills.value.find(x=>x.id===form.value.active_skill)?.name||'无'}]}catch(e){msg.error(e.response?.data?.detail||e.message)}}
async function save(){saving.value=true;try{await http.put('',{...form.value,provider:'DeepSeek',api_url:'https://api.deepseek.com'});msg.success('已保存');await load()}catch(e){msg.error(e.response?.data?.detail||e.message)}finally{saving.value=false}}
async function test(){testing.value=true;try{const r=await http.post('/test');msg.success('连接成功：'+(r.data.data.reply||'DeepSeek 已响应'))}catch(e){msg.error(e.response?.data?.detail||e.message)}finally{testing.value=false}}
async function preview(){try{prompt.value=(await http.get('/prompt')).data.data.prompt;visible.value=true}catch(e){msg.error(e.response?.data?.detail||e.message)}}
onMounted(()=>{load();loadResults()})
</script>
<style scoped>.settings{max-width:920px;margin:35px auto;padding:20px}</style>